css:
.imgrow{display:flex; flex-wrap:wrap; gap:18px; align-items:flex-start; margin:10px 0}
.imgrow figure{margin:0; display:grid; gap:6px; justify-items:center}
.imgrow canvas{width:192px; height:192px; image-rendering:pixelated; border:1px solid var(--rule); border-radius:6px; background:#fff}
.imgrow svg{width:260px; height:200px}
.imgrow figcaption{font-family:var(--display); font-size:13px; color:var(--muted); text-align:center; max-width:240px}
table.lnk{border-collapse:collapse; font-family:var(--mono); font-size:13px}
table.lnk th{font-weight:400; color:var(--muted); padding:2px 6px}
table.lnk td{text-align:center; padding:2px}
.lk{width:30px; height:28px; border:1px solid var(--rule); border-radius:6px; background:var(--panel); font-family:var(--mono); cursor:pointer; color:var(--ink)}
.lk[aria-pressed="true"]{background:var(--c1); border-color:var(--c1); color:var(--panel)}
